using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool, Description("Fetches data from an external API by resource path.")]
    public static async Task<string> FetchExternalData(
        IHttpClientFactory httpClientFactory,
        [Description("The API resource path, e.g. \"users/1\".")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken),
            cancellationToken: cancellationToken);

        return JsonSerializer.Serialize(doc, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerPromptType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks for a concise summary of the provided text.")]
    public static ChatMessage[] Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum number of sentences for the summary.")] int? maxSentences = null)
    {
        var constraint = maxSentences.HasValue
            ? $" Limit the summary to {maxSentences.Value} sentence(s)."
            : string.Empty;

        return
        [
            new(ChatRole.User,
                $"Please provide a concise summary of the following text.{constraint}\n\n{text}")
        ];
    }
}

